use moloch_live_runtime::{semantic_states::*,daily_windows};
use baal_transport_service::{Receipt,Scope};
use serde_json::{Value,json};
use sha2::{Sha256,Digest};
use std::collections::{BTreeMap,BTreeSet};
const NOW:u64=1792112400000;
fn sha<T:serde::Serialize>(v:&T)->String{format!("{:x}",Sha256::digest(serde_json::to_vec(v).unwrap()))}
fn raw(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn receipt(m:&str,c:&str)->Value{let at=daily_windows::iso(NOW-1000).unwrap();json!({"status":200,"endpoint":format!("/markets/{m}/nodes?tournamentId=t"),"requestStartedAt":at,"receivedAt":at,"data":{"market_id":m,"root":{"node_type":"contract","node_id":c,"contract_id":c,"contract_type":"Election Outcome","contract_details":{"contractType":"Election Outcome","raceName":"U.S. Senate North Carolina","resolutionType":"Party Winner","officeLevel":"Federal","usState":"NC","winnerName":"Democratic Party","raceStage":"General","raceId":"62975","stageId":"98105","electionDate":"2026-11-03"},"settled_with":null,"settlement_date":"2026-11-04T17:00:00.000Z","title":"Will the Democratic Party win the North Carolina Senate?"}}})}
fn fixture()->(Review,Vec<Vec<u8>>){let nodes=vec![receipt("277","278"),receipt("278","279")];let bytes:Vec<_>=nodes.iter().map(|n|serde_json::to_vec(n).unwrap()).collect();let contracts=nodes.iter().enumerate().map(|(i,n)|Contract{market_id:(277+i).to_string(),exchange_id:(966+i).to_string(),contract_id:(278+i).to_string(),official_root_sha256:sha(&n["data"]["root"]),original_node_sha256:raw(&bytes[i]),predicate:"Explicit reviewed party winner; affiliation/fusion/finality not inferred from title".into(),unresolved_exceptions:vec!["Full resolver language absent; operator interpretation is an assumption".into()]}).collect();let sources=bytes.iter().map(|b|Source{sha256:raw(b),observed_at_ms:NOW-1000,maximum_age_ms:100000}).collect();let hashes=bytes.iter().map(|b|raw(b)).collect::<Vec<_>>();let states=vec![State{id:"atlas:000000".into(),kind:StateKind::PartyWinner,outcomes:vec![PayoutRule::ResolvedYes,PayoutRule::ResolvedNo],source_sha256:hashes.clone(),assumption_label:"Reviewed ordinary mapping".into()},State{id:"cancel-one".into(),kind:StateKind::Cancelled,outcomes:vec![PayoutRule::RefundPrincipal,PayoutRule::ResolvedYes],source_sha256:hashes,assumption_label:"Explicit asymmetric cancellation stress, not an assumed shared refund".into()}];(Review{version:1,review_id:"semantic-test".into(),run_id:"run".into(),bank_manifest_sha256:"a".repeat(64),tournament_id:"t".into(),tournament_slug:"s".into(),scenario_source_sha256:"b".repeat(64),reviewed_at_ms:NOW-500,valid_until_ms:NOW+100000,contracts,states,sources,excluded_states:vec!["Unmodeled legal challenge variants remain excluded".into()],probabilities_are_reviewed_assumptions:true,exception_weights_ppm:BTreeMap::from([("cancel-one".into(),10000)])},bytes)}
fn compiled(r:&Review,bytes:&[Vec<u8>])->moloch_live_runtime::feedback::Result<Compiled>{let review=serde_json::to_vec(r)?;let expected=raw(&review);let hashes=bytes.iter().map(|b|raw(b)).collect::<Vec<_>>();compile(&review,&expected,&BTreeSet::from([expected.clone()]),&bytes.iter().zip(&hashes).map(|(b,h)|OriginalSource{sha256:h,bytes:b}).collect::<Vec<_>>(),NOW)}
#[test]fn actual_schema_party_predicate_and_asymmetric_refund_compile(){let(r,b)=fixture();let c=compiled(&r,&b).unwrap();assert_eq!(c.contracts()[0].contract_id,"278");assert_eq!(c.states()[1].outcomes[1],PayoutRule::ResolvedYes);assert_eq!(c.exception_weights_ppm()["cancel-one"],10000);}
#[test]fn retained_nc_official_root_is_exact_but_not_a_complete_refund_resolver(){let r=receipt("277","278");assert_eq!(sha(&r["data"]["root"]),"56670f0ec4ec7e9837de07ca07cc7573996a89e94d578f9db675252613936da1");assert!(r["data"]["root"]["contract_details"].get("fusion").is_none());assert!(r["data"]["root"]["contract_details"].get("refund").is_none());}
#[test]fn refund_is_original_principal_and_never_fees_or_universal_dollar(){assert_eq!(PayoutRule::RefundPrincipal.payout(Side::Yes,5,3_125_000).unwrap(),3_125_000);assert_eq!(PayoutRule::RefundPrincipal.payout(Side::No,5,1_250_000).unwrap(),1_250_000);assert_eq!(PayoutRule::ResolvedNo.payout(Side::No,5,1_250_000).unwrap(),5_000_000);assert!(PayoutRule::RefundPrincipal.payout(Side::No,1,1_000_001).is_err());}
#[test]fn original_source_tamper_and_unapproved_review_deny(){let(r,mut b)=fixture();b[0].push(b' ');assert!(compiled(&r,&b).is_err());let(r,b)=fixture();let review=serde_json::to_vec(&r).unwrap();assert!(compile(&review,&raw(&review),&BTreeSet::new(),&b.iter().map(|b|OriginalSource{sha256:"",bytes:b}).collect::<Vec<_>>(),NOW).is_err());}
#[test]fn duplicate_exchange_state_and_missing_source_deny(){let(mut r,b)=fixture();r.contracts[1].exchange_id=r.contracts[0].exchange_id.clone();assert!(compiled(&r,&b).is_err());let(mut r,b)=fixture();r.states[1].id=r.states[0].id.clone();assert!(compiled(&r,&b).is_err());let(mut r,b)=fixture();r.states[0].source_sha256=vec!["f".repeat(64)];assert!(compiled(&r,&b).is_err());}
#[test]fn exception_mass_not_silently_inferred_or_overfull(){let(mut r,b)=fixture();r.exception_weights_ppm.insert("atlas:000000".into(),1);assert!(compiled(&r,&b).is_err());let(mut r,b)=fixture();r.exception_weights_ppm.insert("cancel-one".into(),1_000_000);assert!(compiled(&r,&b).is_err());}
#[test]fn cancelled_label_does_not_invent_refund(){let(mut r,b)=fixture();r.states[1].outcomes=vec![PayoutRule::ResolvedNo;2];assert!(compiled(&r,&b).is_err());}
#[test]fn original_clock_after_review_and_source_expiry_deny(){let(mut r,b)=fixture();r.sources[0].observed_at_ms=NOW;assert!(compiled(&r,&b).is_err());let(mut r,b)=fixture();r.sources[0].maximum_age_ms=500;assert!(compiled(&r,&b).is_err());}
#[test]fn current_receipts_bind_full_opaque_root_scope_and_original_clocks(){let(r,b)=fixture();let c=compiled(&r,&b).unwrap();let scope=Scope{tournament_id:"t".into(),tournament_slug:"s".into(),exchanges:BTreeMap::from([("966".into(),"277".into()),("967".into(),"278".into())])};let mut receipts=BTreeMap::new();for(i,node)in b.iter().enumerate(){let v:Value=serde_json::from_slice(node).unwrap();let receipt:Receipt=serde_json::from_value(v).unwrap();receipts.insert((966+i).to_string(),receipt);}c.validate_current_contracts(&scope,&receipts,NOW).unwrap();receipts.get_mut("966").unwrap().data["root"]["contract_details"]["opaque_new_exception"]=json!(true);assert!(c.validate_current_contracts(&scope,&receipts,NOW).is_err());}
#[test]fn fresh_transport_does_not_hide_stale_or_future_request(){let(r,b)=fixture();let c=compiled(&r,&b).unwrap();let scope=Scope{tournament_id:"t".into(),tournament_slug:"s".into(),exchanges:BTreeMap::from([("966".into(),"277".into()),("967".into(),"278".into())])};let mut receipts:BTreeMap<String,Receipt>=b.iter().enumerate().map(|(i,b)|((966+i).to_string(),serde_json::from_slice(b).unwrap())).collect();receipts.get_mut("966").unwrap().request_started_at=daily_windows::iso(NOW-10001).unwrap();assert!(c.validate_current_contracts(&scope,&receipts,NOW).is_err());receipts.get_mut("966").unwrap().request_started_at=daily_windows::iso(NOW+1).unwrap();assert!(c.validate_current_contracts(&scope,&receipts,NOW).is_err());}
